namespace Mageplaza\Blog\Ui\Component\Listing\Columns;

use Magento\Framework\Escaper;
use Magento\Framework\View\Element\UiComponent\ContextInterface;
use Magento\Framework\View\Element\UiComponentFactory;
use Magento\Ui\Component\Listing\Columns\Column;

/**
 * Escapes the guest-supplied comment author name.
 *
 * The column renders through `ui/grid/cells/html`, so the raw value would be
 * interpreted as markup in the admin grid.
 *
 * @package Mageplaza\Blog\Ui\Component\Listing\Columns
 */
class CommentUserName extends Column
{
    /**
     * @var Escaper
     */
    protected $escaper;

    /**
     * CommentUserName constructor.
     *
     * @param ContextInterface $context
     * @param UiComponentFactory $uiComponentFactory
     * @param Escaper $escaper
     * @param array $components
     * @param array $data
     */
    public function __construct(
        ContextInterface $context,
        UiComponentFactory $uiComponentFactory,
        Escaper $escaper,
        array $components = [],
        array $data = []
    ) {
        $this->escaper = $escaper;

        parent::__construct($context, $uiComponentFactory, $components, $data);
    }

    /**
     * Prepare Data Source
     *
     * @param array $dataSource
     *
     * @return array
     */
    public function prepareDataSource(array $dataSource)
    {
        if (isset($dataSource['data']['items'])) {
            foreach ($dataSource['data']['items'] as & $item) {
                if (isset($item['user_name'])) {
                    $item['user_name'] = $this->escaper->escapeHtml($item['user_name']);
                }
            }
        }

        return $dataSource;
    }
}
